import assert from 'node:assert/strict';
import { execFileSync, spawnSync } from 'node:child_process';
import { chmodSync, mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import test from 'node:test';

const scriptPath = fileURLToPath(new URL('./push-runtime-tool-update-branch.sh', import.meta.url));
const workflowPath = fileURLToPath(
  new URL('../.github/workflows/runtime-tool-updates.yml', import.meta.url),
);
const gitPath = execFileSync('sh', ['-c', 'command -v git'], { encoding: 'utf8' }).trim();
const branch = 'automation/runtime-tool-updates';

function git(cwd, ...args) {
  return execFileSync(gitPath, args, { cwd, encoding: 'utf8' }).trim();
}

function commitFile(repo, name, content, message) {
  writeFileSync(join(repo, name), content);
  git(repo, 'add', name);
  git(repo, 'commit', '-m', message);
  return git(repo, 'rev-parse', 'HEAD');
}

function createFixture({ existingBranch }) {
  const root = mkdtempSync(join(tmpdir(), 'clawscan-runtime-lease-'));
  const remote = join(root, 'remote.git');
  const seed = join(root, 'seed');
  const worker = join(root, 'worker');

  mkdirSync(seed);
  git(root, 'init', '--bare', remote);
  git(seed, 'init');
  git(seed, 'config', 'user.name', 'Test Seed');
  git(seed, 'config', 'user.email', 'seed@example.com');
  commitFile(seed, 'README.md', 'main\n', 'initial main');
  git(seed, 'branch', '-M', 'main');
  git(seed, 'remote', 'add', 'origin', remote);
  git(seed, 'push', '-u', 'origin', 'main');

  if (existingBranch) {
    git(seed, 'switch', '-c', branch);
    commitFile(seed, 'runtime.txt', 'old\n', 'old runtime update');
    git(seed, 'push', 'origin', `HEAD:refs/heads/${branch}`);
    git(seed, 'switch', 'main');
  }

  git(root, 'clone', '--branch', 'main', remote, worker);
  git(worker, 'config', 'user.name', 'Test Worker');
  git(worker, 'config', 'user.email', 'worker@example.com');
  const workerHead = commitFile(worker, 'runtime.txt', 'new\n', 'new runtime update');

  return { root, remote, worker, workerHead };
}

function runPush(worker, env = process.env) {
  return spawnSync('bash', [scriptPath, 'origin', branch], {
    cwd: worker,
    env,
    encoding: 'utf8',
  });
}

function remoteHead(remote) {
  return git(remote, 'rev-parse', `refs/heads/${branch}`);
}

function installRacingHook(fixture, { branchExists }) {
  const racer = join(fixture.root, 'racer');
  git(fixture.root, 'clone', '--branch', branchExists ? branch : 'main', fixture.remote, racer);
  git(racer, 'config', 'user.name', 'Test Racer');
  git(racer, 'config', 'user.email', 'racer@example.com');
  if (!branchExists) {
    git(racer, 'switch', '-c', branch);
  }
  const racerHead = commitFile(racer, 'race.txt', 'race\n', 'competing runtime update');

  const hook = join(fixture.worker, '.git', 'hooks', 'pre-push');
  writeFileSync(
    hook,
    `#!/bin/sh\nset -eu\n"${gitPath}" -C "${racer}" push origin HEAD:refs/heads/${branch} >/dev/null\n`,
  );
  chmodSync(hook, 0o755);
  return racerHead;
}

function installFetchRaceWrapper(fixture) {
  const racer = join(fixture.root, 'fetch-racer');
  git(fixture.root, 'clone', '--branch', branch, fixture.remote, racer);
  git(racer, 'config', 'user.name', 'Test Fetch Racer');
  git(racer, 'config', 'user.email', 'fetch-racer@example.com');
  const racerHead = commitFile(racer, 'fetch-race.txt', 'race\n', 'competing fetch-time update');

  const bin = join(fixture.root, 'bin');
  const marker = join(fixture.root, 'fetch-race-fired');
  mkdirSync(bin);
  const wrapper = join(bin, 'git');
  writeFileSync(
    wrapper,
    `#!/bin/sh
set -eu
if [ "\${1:-}" = "fetch" ] && [ ! -e "${marker}" ]; then
  : > "${marker}"
  "${gitPath}" -C "${racer}" push origin HEAD:refs/heads/${branch} >/dev/null
fi
exec "${gitPath}" "$@"
`,
  );
  chmodSync(wrapper, 0o755);
  return {
    env: { ...process.env, PATH: `${bin}:${process.env.PATH}` },
    racerHead,
  };
}

test('creates the automation branch only while it remains absent', () => {
  const fixture = createFixture({ existingBranch: false });
  try {
    const result = runPush(fixture.worker);
    assert.equal(result.status, 0, result.stderr);
    assert.equal(remoteHead(fixture.remote), fixture.workerHead);
  } finally {
    rmSync(fixture.root, { recursive: true, force: true });
  }
});

test('replaces the observed automation branch tip', () => {
  const fixture = createFixture({ existingBranch: true });
  try {
    const result = runPush(fixture.worker);
    assert.equal(result.status, 0, result.stderr);
    assert.equal(remoteHead(fixture.remote), fixture.workerHead);
  } finally {
    rmSync(fixture.root, { recursive: true, force: true });
  }
});

test('rejects a competing update after observing an existing branch', () => {
  const fixture = createFixture({ existingBranch: true });
  try {
    const racerHead = installRacingHook(fixture, { branchExists: true });
    const result = runPush(fixture.worker);
    assert.notEqual(result.status, 0);
    assert.equal(remoteHead(fixture.remote), racerHead);
  } finally {
    rmSync(fixture.root, { recursive: true, force: true });
  }
});

test('rejects a competing update between observation and fetch', () => {
  const fixture = createFixture({ existingBranch: true });
  try {
    const race = installFetchRaceWrapper(fixture);
    const result = runPush(fixture.worker, race.env);
    assert.notEqual(result.status, 0);
    assert.match(result.stderr, /changed while its lease was being prepared/u);
    assert.equal(remoteHead(fixture.remote), race.racerHead);
  } finally {
    rmSync(fixture.root, { recursive: true, force: true });
  }
});

test('rejects a competing branch creation after observing it absent', () => {
  const fixture = createFixture({ existingBranch: false });
  try {
    const racerHead = installRacingHook(fixture, { branchExists: false });
    const result = runPush(fixture.worker);
    assert.notEqual(result.status, 0);
    assert.equal(remoteHead(fixture.remote), racerHead);
  } finally {
    rmSync(fixture.root, { recursive: true, force: true });
  }
});

test('workflow serializes writers and delegates the guarded push', () => {
  const workflow = readFileSync(workflowPath, 'utf8');
  assert.match(workflow, /group: runtime-tool-updates/u);
  assert.match(workflow, /cancel-in-progress: false/u);
  assert.match(workflow, /scripts\/push-runtime-tool-update-branch\.sh origin "\$BRANCH"/u);
  assert.doesNotMatch(workflow, /git push --force-with-lease origin "\$BRANCH"/u);
});

package schemas_test

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/openclaw/clawscan/internal/runner"
	jsonschema "github.com/santhosh-tekuri/jsonschema/v6"
	"gopkg.in/yaml.v3"
)

func TestClawScanSchemaAcceptsSupportedProfiles(t *testing.T) {
	schema := compileClawScanSchema(t)
	fixtures := map[string][]byte{
		"embedded clawhub profile": readFixture(t, filepath.Join("..", "internal", "profiles", "clawhub", "clawscan.yml")),
		"custom scanner and gate": []byte(`
version: 1
sandbox:
  mode: docker
  image: ghcr.io/openclaw/clawscan-runtime:latest
  env: [OPENAI_API_KEY]
  mounts:
    - /opt/rules
    - path: /var/cache/clawscan
      write: true
profiles:
  review:
    scanners:
      - skillspector
      - id: clawscan-static
        gate:
          rules:
            - id: any-finding
              path: findings[]
              exists: true
              action: warn
      - id: third-party
        command: third-party scan --json {{target}}
        env: [THIRD_PARTY_REGION]
        secretEnv: <REDACTED>
        targets: [skill, plugin, url]
        gate:
          blockOnExitCode: nonzero
          warnOnExitCode: [1, 2]
          rules:
            - id: critical-risk
              path:
                - result.risk
                - result.risk_level
              equals: critical
              normalize: identifier
              fallback: root
              action: block
    scannerResults:
      skillspector: ./fixtures/skillspector.json
    output: ./artifacts/review.json
    json: true
    judge:
      command: judge --input {{ workspace }} --output {{ output }}
`),
	}

	for name, data := range fixtures {
		t.Run(name, func(t *testing.T) {
			if err := schema.Validate(decodeYAMLAsJSON(t, data)); err != nil {
				t.Fatalf("schema rejected supported profile: %v", err)
			}
		})
	}
}

func TestClawScanSchemaAcceptsEveryBuiltInScanner(t *testing.T) {
	schema := compileClawScanSchema(t)
	for _, scannerID := range runner.DefaultScannerRegistry().IDs() {
		t.Run(scannerID, func(t *testing.T) {
			data := []byte("version: 1\nprofiles:\n  review:\n    scanners:\n      - " + scannerID + "\n")
			if err := schema.Validate(decodeYAMLAsJSON(t, data)); err != nil {
				t.Fatalf("schema rejected built-in scanner %q: %v", scannerID, err)
			}
		})
	}
}

func TestClawScanSchemaRejectsInvalidGateRules(t *testing.T) {
	schema := compileClawScanSchema(t)
	tests := map[string]string{
		"unknown field": `
          - id: risky
            path: result.risk
            equals: critical
            aciton: block
`,
		"invalid action": `
          - id: risky
            path: result.risk
            equals: critical
            action: deny
`,
		"false exists": `
          - id: risky
            path: result.risk
            exists: false
            action: block
`,
		"both conditions": `
          - id: risky
            path: result.risk
            equals: critical
            exists: true
            action: block
`,
		"numeric normalization": `
          - id: risky
            path: result.score
            equals: 10
            normalize: identifier
            action: block
`,
		"empty path list": `
          - id: risky
            path: []
            exists: true
            action: block
`,
		"indexed scalar path": `
          - id: risky
            path: "findings[0].severity"
            equals: critical
            action: block
`,
		"indexed path in list": `
          - id: risky
            path: [result.risk, "findings[0].severity"]
            equals: critical
            action: block
`,
	}

	for name, rules := range tests {
		t.Run(name, func(t *testing.T) {
			data := []byte("version: 1\nprofiles:\n  review:\n    scanners:\n      - id: demo\n        command: demo {{target}}\n        gate:\n          rules:\n" + rules)
			if err := schema.Validate(decodeYAMLAsJSON(t, data)); err == nil {
				t.Fatal("schema accepted invalid gate rule")
			}
		})
	}
}

func TestClawScanSchemaRejectsInvalidScannerDeclarations(t *testing.T) {
	schema := compileClawScanSchema(t)
	tests := map[string]string{
		"unknown built-in": "not-a-scanner",
		"custom scanner without target": `
        id: custom
        command: custom scan
`,
		"built-in scanner overridden as custom": `
        id: snyk
        command: custom scan {{target}}
`,
	}

	for name, scanner := range tests {
		t.Run(name, func(t *testing.T) {
			data := []byte("version: 1\nprofiles:\n  review:\n    scanners:\n      - " + scanner)
			if err := schema.Validate(decodeYAMLAsJSON(t, data)); err == nil {
				t.Fatal("schema accepted invalid scanner declaration")
			}
		})
	}
}

func compileClawScanSchema(t *testing.T) *jsonschema.Schema {
	t.Helper()
	data := readFixture(t, "clawscan.schema.json")
	document, err := jsonschema.UnmarshalJSON(bytes.NewReader(data))
	if err != nil {
		t.Fatalf("decode schema: %v", err)
	}
	compiler := jsonschema.NewCompiler()
	compiler.DefaultDraft(jsonschema.Draft2020)
	if err := compiler.AddResource("clawscan.schema.json", document); err != nil {
		t.Fatalf("add schema resource: %v", err)
	}
	schema, err := compiler.Compile("clawscan.schema.json")
	if err != nil {
		t.Fatalf("compile schema: %v", err)
	}
	return schema
}

func decodeYAMLAsJSON(t *testing.T, data []byte) any {
	t.Helper()
	var value any
	decoder := yaml.NewDecoder(bytes.NewReader(data))
	decoder.KnownFields(false)
	if err := decoder.Decode(&value); err != nil {
		t.Fatalf("decode YAML fixture: %v", err)
	}
	encoded, err := json.Marshal(value)
	if err != nil {
		t.Fatalf("encode YAML fixture as JSON: %v", err)
	}
	jsonDecoder := json.NewDecoder(bytes.NewReader(encoded))
	jsonDecoder.UseNumber()
	if err := jsonDecoder.Decode(&value); err != nil {
		t.Fatalf("decode normalized JSON fixture: %v", err)
	}
	return value
}

func readFixture(t *testing.T, path string) []byte {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	return data
}

func TestProfileDocsAdvertiseThePublishedSchema(t *testing.T) {
	docs := readFixture(t, filepath.Join("..", "docs", "profiles.md"))
	const directive = "# yaml-language-server: $schema=https://raw.githubusercontent.com/openclaw/clawscan/main/schemas/clawscan.schema.json"
	if !strings.Contains(string(docs), directive) {
		t.Fatalf("profile docs do not include schema directive %q", directive)
	}
}

package installpolicy

import (
	"bytes"
	"encoding/json"
	"strings"
	"testing"
	"unicode"

	"github.com/openclaw/clawscan/internal/runner"
)

func TestDecodeRequestAcceptsSkillAndPluginPayloads(t *testing.T) {
	tests := []struct {
		name       string
		targetType string
		request    string
		wantKind   string
	}{
		{
			name:       "skill",
			targetType: "skill",
			wantKind:   "skill-install",
			request: `{
				"protocolVersion": 1,
				"openclawVersion": "2026.7.2",
				"targetType": "skill",
				"targetName": "weather",
				"sourcePath": "/tmp/staged/weather",
				"sourcePathKind": "directory",
				"source": {"kind":"clawhub","authority":"third-party","mutable":false,"network":true},
				"origin": {"type":"clawhub","slug":"weather","version":"1.0.0"},
				"request": {"kind":"skill-install","mode":"install","requestedSpecifier":"clawhub:weather@1.0.0"},
				"skill": {"installId":"clawhub"}
			}`,
		},
		{
			name:       "plugin",
			targetType: "plugin",
			wantKind:   "plugin-git",
			request: `{
				"protocolVersion": 1,
				"openclawVersion": "2026.7.2",
				"targetType": "plugin",
				"targetName": "example",
				"sourcePath": "/tmp/staged/example",
				"sourcePathKind": "directory",
				"source": {"kind":"git","authority":"third-party","mutable":true,"network":true},
				"origin": {"type":"git","url":"https://example.invalid/plugin.git","commit":"abc123"},
				"request": {"kind":"plugin-git","mode":"update","requestedSpecifier":"git:https://example.invalid/plugin.git"},
				"plugin": {"pluginId":"example","contentType":"bundle","manifestId":"example","version":"2.0.0"}
			}`,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			request, err := DecodeRequest(strings.NewReader(test.request))
			if err != nil {
				t.Fatal(err)
			}
			if request.TargetType != test.targetType {
				t.Fatalf("targetType = %q, want %q", request.TargetType, test.targetType)
			}
			if request.Request.Kind != test.wantKind {
				t.Fatalf("request.kind = %q, want %q", request.Request.Kind, test.wantKind)
			}
			if request.Origin["type"] == nil || request.Source == nil {
				t.Fatalf("source/origin metadata was not preserved: %#v", request)
			}
			if request.TargetType == "plugin" &&
				(request.Plugin == nil || request.Plugin.ContentType != "bundle") {
				t.Fatalf("plugin metadata was not preserved: %#v", request.Plugin)
			}
		})
	}
}

func TestDecodeRequestRejectsInvalidOrOversizedPayloads(t *testing.T) {
	tests := []struct {
		name    string
		payload string
		want    string
	}{
		{name: "malformed", payload: `{`, want: "invalid JSON"},
		{name: "protocol", payload: `{"protocolVersion":2}`, want: "protocolVersion must be 1"},
		{
			name: "target",
			payload: `{
				"protocolVersion":1,
				"targetType":"channel",
				"targetName":"demo",
				"sourcePath":"/tmp/demo",
				"sourcePathKind":"directory",
				"origin":{"type":"test"},
				"request":{"kind":"skill-install","mode":"install"}
			}`,
			want: `targetType must be "skill" or "plugin"`,
		},
		{
			name:    "oversized",
			payload: `{"protocolVersion":1,"padding":"` + strings.Repeat("x", maxRequestBytes) + `"}`,
			want:    "exceeds",
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			if _, err := DecodeRequest(strings.NewReader(test.payload)); err == nil || !strings.Contains(err.Error(), test.want) {
				t.Fatalf("error = %v, want containing %q", err, test.want)
			}
		})
	}
}

func TestResponseFromArtifactMapsGateAndScannerState(t *testing.T) {
	exitCode := 3
	tests := []struct {
		name     string
		artifact runner.Artifact
		decision string
		reason   bool
		findings int
	}{
		{
			name: "pass",
			artifact: runner.Artifact{
				Gate: "pass",
				Scanners: map[string]runner.ScannerResult{"static": {
					Status: "completed",
					Raw:    json.RawMessage(`{"findings":[]}`),
				}},
			},
			decision: "allow",
		},
		{
			name: "warn",
			artifact: runner.Artifact{
				Gate: "warn",
				Scanners: map[string]runner.ScannerResult{"static": {
					Status: "completed",
					Raw:    json.RawMessage(`{"findings":[]}`),
				}},
				GateRules: []runner.FiredGateRule{{
					Scanner: "static",
					Rule:    "finding",
					Path:    "findings[]",
					Action:  "warn",
				}},
			},
			decision: "warn",
			reason:   true,
			findings: 1,
		},
		{
			name: "block",
			artifact: runner.Artifact{
				Gate: "block",
				Scanners: map[string]runner.ScannerResult{"static": {
					Status: "completed",
					Raw:    json.RawMessage(`{"findings":[]}`),
				}},
				GateRules: []runner.FiredGateRule{{
					Scanner:  "static",
					Rule:     "exit-code",
					ExitCode: &exitCode,
					Action:   "block",
				}},
			},
			decision: "block",
			reason:   true,
			findings: 1,
		},
		{
			name: "unusable completed evidence",
			artifact: runner.Artifact{
				Gate: "pass",
				Scanners: map[string]runner.ScannerResult{
					"skillspector": {Status: "completed", Raw: json.RawMessage(`{}`)},
				},
			},
			decision: "block",
			reason:   true,
		},
		{
			name: "scanner failure",
			artifact: runner.Artifact{
				Gate:     "pass",
				Scanners: map[string]runner.ScannerResult{"static": {Status: "failed", Error: "boom"}},
			},
			decision: "block",
			reason:   true,
		},
		{
			name: "scanner skipped",
			artifact: runner.Artifact{
				Gate:     "pass",
				Scanners: map[string]runner.ScannerResult{"static": {Status: "skipped"}},
			},
			decision: "block",
			reason:   true,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			response := ResponseFromArtifact(test.artifact)
			if response.Decision != test.decision ||
				(strings.TrimSpace(response.Reason) != "") != test.reason {
				t.Fatalf("response = %#v", response)
			}
			if len(response.Findings) != test.findings {
				t.Fatalf("findings = %#v, want %d", response.Findings, test.findings)
			}
		})
	}
}

func TestFailureResponseAndWriteResponseUsePolicyProtocol(t *testing.T) {
	response := FailureResponse("scanner exploded")
	var output bytes.Buffer
	if err := WriteResponse(&output, response); err != nil {
		t.Fatal(err)
	}

	var decoded map[string]any
	if err := json.Unmarshal(output.Bytes(), &decoded); err != nil {
		t.Fatal(err)
	}
	if decoded["protocolVersion"] != float64(1) ||
		decoded["decision"] != "block" ||
		strings.TrimSpace(decoded["reason"].(string)) == "" {
		t.Fatalf("response = %#v", decoded)
	}
	if _, exists := decoded["code"]; exists {
		t.Fatalf("response contains non-contract code field: %#v", decoded)
	}
}

func TestWriteResponseSanitizesControlCharactersInAllDiagnosticText(t *testing.T) {
	response := Response{
		ProtocolVersion: 1,
		Decision:        "block",
		Reason:          "first line\nforged line\tend",
		Findings: []Finding{{
			RuleID:   "scanner.\x00rule",
			Severity: "critical",
			Message:  "message\r\nnext",
			Evidence: "path=\x1b[2J/tmp/demo",
		}},
	}
	var output bytes.Buffer
	if err := WriteResponse(&output, response); err != nil {
		t.Fatal(err)
	}
	var decoded Response
	if err := json.Unmarshal(output.Bytes(), &decoded); err != nil {
		t.Fatal(err)
	}
	for name, value := range map[string]string{
		"reason":   decoded.Reason,
		"ruleId":   decoded.Findings[0].RuleID,
		"message":  decoded.Findings[0].Message,
		"evidence": decoded.Findings[0].Evidence,
	} {
		for _, character := range value {
			if unicode.IsControl(character) {
				t.Fatalf("%s retained control character in %q", name, value)
			}
		}
	}
	if decoded.Reason != "first line forged line end" {
		t.Fatalf("reason = %q", decoded.Reason)
	}
}

func TestWriteResponseRequiresReasonsForWarnAndBlock(t *testing.T) {
	for _, decision := range []string{"warn", "block"} {
		t.Run(decision, func(t *testing.T) {
			var output bytes.Buffer
			err := WriteResponse(&output, Response{
				ProtocolVersion: 1,
				Decision:        decision,
				Reason:          "\n\t",
			})
			if err == nil || !strings.Contains(err.Error(), "requires a non-empty reason") {
				t.Fatalf("error = %v", err)
			}
			if output.Len() != 0 {
				t.Fatalf("invalid response reached stdout: %q", output.String())
			}
		})
	}
}

func TestWriteResponseRejectsUnsupportedDecision(t *testing.T) {
	var output bytes.Buffer
	err := WriteResponse(&output, Response{ProtocolVersion: 1, Decision: "confirm"})
	if err == nil || !strings.Contains(err.Error(), `"allow", "warn", or "block"`) {
		t.Fatalf("error = %v", err)
	}
}

func TestResponseFromArtifactBoundsUntrustedFindingOutput(t *testing.T) {
	rules := make([]runner.FiredGateRule, maxFindings)
	for index := range rules {
		rules[index] = runner.FiredGateRule{
			Scanner: "static",
			Rule:    strings.Repeat("r", maxTextRunes+20),
			Path:    strings.Repeat("p", maxTextRunes+20),
			Action:  "warn",
		}
	}
	response := ResponseFromArtifact(runner.Artifact{
		Gate:      "warn",
		GateRules: rules,
		Scanners: map[string]runner.ScannerResult{"static": {
			Status: "completed",
			Raw:    json.RawMessage(`{"findings":[]}`),
		}},
	})
	if len(response.Findings) != maxFindings {
		t.Fatalf("findings = %d, want %d", len(response.Findings), maxFindings)
	}
	if len([]rune(response.Findings[0].RuleID)) > maxTextRunes+3 ||
		len([]rune(response.Findings[0].Evidence)) > maxTextRunes+3 {
		t.Fatalf("finding was not bounded: %#v", response.Findings[0])
	}
}

func TestAddFindingPreservesProtocolFindingBound(t *testing.T) {
	response := Response{
		ProtocolVersion: 1,
		Decision:        "allow",
		Findings:        make([]Finding, maxFindings),
	}
	AddFinding(&response, Finding{RuleID: "info", Severity: "info"})
	if len(response.Findings) != maxFindings {
		t.Fatalf("findings = %d", len(response.Findings))
	}
	AddFinding(&response, Finding{RuleID: "fallback", Severity: "warn"})
	if response.Findings[maxFindings-1].RuleID != "fallback" {
		t.Fatalf("visible warning was not retained: %#v", response.Findings[maxFindings-1])
	}
}

