func captureStdout(t *testing.T, fn func()) string {
	t.Helper()

	original := os.Stdout
	read, write, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	os.Stdout = write
	t.Cleanup(func() {
		os.Stdout = original
	})

	fn()

	if err := write.Close(); err != nil {
		t.Fatal(err)
	}
	out, err := io.ReadAll(read)
	if err != nil {
		t.Fatal(err)
	}
	if err := read.Close(); err != nil {
		t.Fatal(err)
	}
	os.Stdout = original
	return string(out)
}

func captureOutput(t *testing.T, fn func()) (string, string) {
	t.Helper()

	originalStdout := os.Stdout
	originalStderr := os.Stderr
	stdoutRead, stdoutWrite, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	stderrRead, stderrWrite, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	os.Stdout = stdoutWrite
	os.Stderr = stderrWrite
	t.Cleanup(func() {
		os.Stdout = originalStdout
		os.Stderr = originalStderr
	})

	fn()

	if err := stdoutWrite.Close(); err != nil {
		t.Fatal(err)
	}
	if err := stderrWrite.Close(); err != nil {
		t.Fatal(err)
	}
	stdout, err := io.ReadAll(stdoutRead)
	if err != nil {
		t.Fatal(err)
	}
	stderr, err := io.ReadAll(stderrRead)
	if err != nil {
		t.Fatal(err)
	}
	if err := stdoutRead.Close(); err != nil {
		t.Fatal(err)
	}
	if err := stderrRead.Close(); err != nil {
		t.Fatal(err)
	}
	os.Stdout = originalStdout
	os.Stderr = originalStderr
	return string(stdout), string(stderr)
}

const root = document.documentElement;
const sidebar = document.querySelector('.sidebar');
const overlay = document.querySelector('.sidebar-overlay');
const menuButton = document.querySelector('.nav-toggle');
const mobileNav = window.matchMedia('(max-width: 52rem)');

function readStoredTheme() {
  try {
    return localStorage.getItem('clawscan-theme');
  } catch {
    return null;
  }
}

function storeTheme(theme) {
  try {
    localStorage.setItem('clawscan-theme', theme);
  } catch {
    // Theme persistence is optional in privacy-restricted browsing modes.
  }
}

function applyTheme(theme) {
  root.dataset.theme = theme;
  document.querySelectorAll('[data-theme-toggle]').forEach((button) => {
    button.setAttribute('aria-pressed', theme === 'dark' ? 'true' : 'false');
    button.setAttribute(
      'aria-label',
      theme === 'dark' ? 'Switch to light theme' : 'Switch to dark theme',
    );
  });
}

applyTheme(root.dataset.theme === 'dark' ? 'dark' : 'light');

document.querySelectorAll('[data-theme-toggle]').forEach((button) => {
  button.addEventListener('click', () => {
    const nextTheme = root.dataset.theme === 'dark' ? 'light' : 'dark';
    applyTheme(nextTheme);
    storeTheme(nextTheme);
  });
});

const systemTheme = window.matchMedia('(prefers-color-scheme: dark)');
const onSystemThemeChange = (event) => {
  if (!readStoredTheme()) {
    applyTheme(event.matches ? 'dark' : 'light');
  }
};

if (systemTheme.addEventListener) {
  systemTheme.addEventListener('change', onSystemThemeChange);
} else {
  systemTheme.addListener?.(onSystemThemeChange);
}

function setNavigationOpen(open) {
  if (!sidebar || !overlay || !menuButton) {
    return;
  }
  const focusWasInSidebar = sidebar.contains(document.activeElement);
  const sidebarIsHidden = mobileNav.matches && !open;
  sidebar.classList.toggle('open', open);
  overlay.classList.toggle('open', open);
  overlay.hidden = !open;
  menuButton.setAttribute('aria-expanded', open ? 'true' : 'false');
  sidebar.toggleAttribute('inert', sidebarIsHidden);
  if (sidebarIsHidden) {
    sidebar.setAttribute('aria-hidden', 'true');
  } else {
    sidebar.removeAttribute('aria-hidden');
  }
  document.body.style.overflow = mobileNav.matches && open ? 'hidden' : '';
  if (sidebarIsHidden && focusWasInSidebar) {
    menuButton.focus();
  }
}

setNavigationOpen(false);
menuButton?.addEventListener('click', () => {
  setNavigationOpen(!sidebar?.classList.contains('open'));
});
overlay?.addEventListener('click', () => setNavigationOpen(false));

document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape') {
    setNavigationOpen(false);
  }
});

const onViewportChange = () => setNavigationOpen(false);
if (mobileNav.addEventListener) {
  mobileNav.addEventListener('change', onViewportChange);
} else {
  mobileNav.addListener?.(onViewportChange);
}

const searchInput = document.getElementById('doc-search');
searchInput?.addEventListener('input', () => {
  const query = searchInput.value.trim().toLowerCase();
  document.querySelectorAll('.docs-nav section').forEach((section) => {
    let hasMatch = false;
    section.querySelectorAll('.nav-link').forEach((link) => {
      const matches = !query || link.textContent.toLowerCase().includes(query);
      link.hidden = !matches;
      hasMatch ||= matches;
    });
    section.hidden = !hasMatch;
  });
});

document.addEventListener('keydown', (event) => {
  const target = event.target;
  const isTyping = target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement;
  if (event.key === '/' && !isTyping && searchInput) {
    event.preventDefault();
    if (mobileNav.matches) {
      setNavigationOpen(true);
    }
    searchInput.focus();
  }
});

async function copyText(button, text) {
  const idleLabel = button.dataset.idleLabel || button.textContent;
  try {
    await navigator.clipboard.writeText(text);
    button.textContent = 'Copied';
    button.classList.add('copied');
  } catch {
    button.textContent = 'Copy failed';
  }
  window.setTimeout(() => {
    button.textContent = idleLabel;
    button.classList.remove('copied');
  }, 1500);
}

document.querySelectorAll('.doc pre').forEach((pre) => {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'copy';
  button.textContent = 'Copy';
  button.dataset.idleLabel = 'Copy';
  button.setAttribute('aria-label', 'Copy code');
  button.addEventListener('click', () => {
    copyText(button, pre.querySelector('code')?.textContent ?? '');
  });
  pre.appendChild(button);
});

document.querySelectorAll('[data-copy-install]').forEach((button) => {
  const label = button.querySelector('.install-copy');
  if (!label) {
    return;
  }
  label.dataset.idleLabel = 'Copy';
  button.addEventListener('click', () => {
    copyText(label, 'npm install -g @openclaw/clawscan');
  });
});

const tocLinks = document.querySelectorAll('.toc a');
if (tocLinks.length && 'IntersectionObserver' in window) {
  const linksByHeading = new Map();
  tocLinks.forEach((link) => {
    const heading = document.getElementById(link.hash.slice(1));
    if (heading) {
      linksByHeading.set(heading, link);
    }
  });

  const observer = new IntersectionObserver(
    (entries) => {
      const visible = entries
        .filter((entry) => entry.isIntersecting)
        .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top);
      const activeLink = visible.length ? linksByHeading.get(visible[0].target) : null;
      if (!activeLink) {
        return;
      }
      tocLinks.forEach((link) => link.classList.toggle('active', link === activeLink));
    },
    { rootMargin: '-18% 0px -68% 0px', threshold: 0 },
  );

  linksByHeading.forEach((_link, heading) => observer.observe(heading));
}

package runner

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"time"
)

var errInvalidCiscoJSON = errors.New("Cisco skill-scanner returned invalid JSON")

func (runner ExternalScannerRunner) runCisco(target string, startedAt string) (ScannerResult, error) {
	resultDir, err := os.MkdirTemp("", "clawscan-cisco-*")
	if err != nil {
		return ScannerResult{}, err
	}
	defer os.RemoveAll(resultDir)

	command := "skill-scanner"
	resultPath := filepath.Join(resultDir, "cisco-skill-scanner.json")
	args := []string{"scan", target, "--format", "json", "--output", resultPath}
	args = append(args, ciscoAnalyzerArgs(runner.Env)...)
	fullCommand := append([]string{command}, args...)
	timeout := runner.Timeout
	if timeout == 0 {
		timeout = 20 * time.Minute
	}

	cwd := ""
	if runner.SandboxMode == SandboxModeDocker {
		cwd = resultDir
	}
	output, runErr := runner.CommandRunner.Run(command, args, cwd, timeout)
	exitCode := gateEligibleExitCode(output.ExitCode)
	raw, readErr := os.ReadFile(resultPath)
	completedAt := time.Now().UTC().Format(time.RFC3339Nano)
	if readErr != nil {
		message := "Cisco skill-scanner did not write JSON output."
		if runErr != nil {
			message = scannerCommandError(runErr, output.Stderr, runner.Env) + ": " + message
		}
		return ScannerResult{
			Status:      "failed",
			StartedAt:   startedAt,
			CompletedAt: completedAt,
			Command:     fullCommand,
			Error:       message,
			Raw:         nil,
		}, nil
	}
	if !json.Valid(raw) {
		message := errInvalidCiscoJSON.Error()
		if runErr != nil {
			message = scannerCommandError(runErr, output.Stderr, runner.Env) + ": " + message
		}
		return ScannerResult{
			Status:      "failed",
			StartedAt:   startedAt,
			CompletedAt: completedAt,
			Command:     fullCommand,
			Error:       message,
			Raw:         nil,
		}, nil
	}
	result := ScannerResult{
		Status:      "completed",
		StartedAt:   startedAt,
		CompletedAt: completedAt,
		Command:     fullCommand,
		Error:       "",
		ExitCode:    exitCode,
		Raw:         json.RawMessage(raw),
	}
	if runErr != nil {
		result.Error = scannerCommandError(runErr, output.Stderr, runner.Env)
		result.Status = commandScannerResultStatus(output, runErr)
	}
	return result, nil
}

func ciscoAnalyzerArgs(env map[string]string) []string {
	var args []string
	if ciscoLLMConfigured(env) || ciscoMetaLLMConfigured(env) {
		args = append(args, "--use-llm")
	}
	if ciscoMetaLLMConfigured(env) {
		args = append(args, "--enable-meta")
	}
	if strings.TrimSpace(env["VIRUSTOTAL_API_KEY"]) != "" {
		args = append(args, "--use-virustotal")
	}
	if strings.TrimSpace(env["AI_DEFENSE_API_KEY"]) != "" || strings.TrimSpace(env["AI_DEFENSE_API_URL"]) != "" {
		args = append(args, "--use-aidefense")
	}
	return args
}

func ciscoLLMConfigured(env map[string]string) bool {
	for _, key := range []string{
		"SKILL_SCANNER_LLM_API_KEY",
		"SKILL_SCANNER_LLM_PROVIDER",
		"SKILL_SCANNER_LLM_MODEL",
		"SKILL_SCANNER_LLM_BASE_URL",
		"SKILL_SCANNER_LLM_USER",
		"SKILL_SCANNER_LLM_API_VERSION",
		"SKILL_SCANNER_LLM_FORCE_JSON_OBJECT",
		"AWS_PROFILE",
		"AWS_REGION",
		"GOOGLE_APPLICATION_CREDENTIALS",
	} {
		if strings.TrimSpace(env[key]) != "" {
			return true
		}
	}
	return false
}

func ciscoMetaLLMConfigured(env map[string]string) bool {
	for _, key := range []string{
		"SKILL_SCANNER_META_LLM_API_KEY",
		"SKILL_SCANNER_META_LLM_MODEL",
		"SKILL_SCANNER_META_LLM_BASE_URL",
		"SKILL_SCANNER_META_LLM_API_VERSION",
	} {
		if strings.TrimSpace(env[key]) != "" {
			return true
		}
	}
	return false
}

package runner

import (
	"crypto/rand"
	"encoding/csv"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"slices"
	"sort"
	"strings"
	"time"
)

const (
	SandboxModeDocker = "docker"
	SandboxModeOff    = "off"

	SandboxRunIDEnv       = "CLAWSCAN_SANDBOX_RUN_ID"
	SandboxRunIDLabel     = "org.openclaw.clawscan.run-id"
	SandboxCommandIDLabel = "org.openclaw.clawscan.command-id"

	DefaultSandboxImage = "ghcr.io/openclaw/clawscan-runtime:latest"
)

var sandboxRunIDPattern = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$`)

type SandboxOptions struct {
	Mode   string
	Image  string
	Env    []string
	Mounts []SandboxMount
}

type SandboxMount struct {
	Path  string `json:"path"`
	Write bool   `json:"write,omitempty"`
}

type SandboxMetadata struct {
	Mode    string         `json:"mode"`
	Image   string         `json:"image,omitempty"`
	Network string         `json:"network,omitempty"`
	Env     []string       `json:"env,omitempty"`
	Mounts  []SandboxMount `json:"mounts,omitempty"`
}

type resolvedSandbox struct {
	Mode  string
	Image string
}

type dockerCommandRunner struct {
	Host     CommandRunner
	Env      map[string]string
	Image    string
	EnvNames []string
	Mounts   []SandboxMount
}

func resolveSandbox(opts Options, env map[string]string) (resolvedSandbox, error) {
	mode := strings.TrimSpace(opts.Sandbox.Mode)
	if mode == "" {
		mode = strings.TrimSpace(env["CLAWSCAN_SANDBOX"])
	}
	if mode == "" {
		mode = SandboxModeDocker
	}
	mode = strings.ToLower(mode)
	if err := validateSandboxMode(mode, "CLAWSCAN_SANDBOX"); err != nil {
		return resolvedSandbox{}, err
	}

	image := strings.TrimSpace(opts.Sandbox.Image)
	if image == "" {
		image = strings.TrimSpace(env["CLAWSCAN_SANDBOX_IMAGE"])
	}
	if image == "" && mode == SandboxModeDocker {
		image = DefaultSandboxImage
	}
	return resolvedSandbox{Mode: mode, Image: image}, nil
}

func validateSandboxMode(mode string, source string) error {
	switch strings.ToLower(strings.TrimSpace(mode)) {
	case SandboxModeDocker, SandboxModeOff:
		return nil
	default:
		return fmt.Errorf("Unsupported %s mode: %s (valid: docker, off)", source, mode)
	}
}

func sandboxMetadata(opts Options, env map[string]string) (SandboxMetadata, error) {
	sandbox, err := resolveSandbox(opts, env)
	if err != nil {
		return SandboxMetadata{}, err
	}
	metadata := SandboxMetadata{Mode: sandbox.Mode}
	if sandbox.Mode == SandboxModeDocker {
		metadata.Image = sandbox.Image
		metadata.Network = "on"
		metadata.Env = sandboxEnvNames(opts, env)
		metadata.Mounts = effectiveSandboxMounts(opts.Sandbox.Mounts)
	}
	return metadata, nil
}

func mustSandboxMetadata(opts Options, env map[string]string) SandboxMetadata {
	metadata, err := sandboxMetadata(opts, env)
	if err != nil {
		return SandboxMetadata{Mode: SandboxModeDocker, Image: DefaultSandboxImage, Network: "on"}
	}
	return metadata
}

func sandboxMetadataForOptionList(optsList []Options, env map[string]string) SandboxMetadata {
	if len(optsList) == 0 {
		return SandboxMetadata{}
	}
	first := mustSandboxMetadata(optsList[0], env)
	for _, opts := range optsList[1:] {
		next := mustSandboxMetadata(opts, env)
		if next.Mode != first.Mode ||
			next.Image != first.Image ||
			next.Network != first.Network ||
			strings.Join(next.Env, "\x00") != strings.Join(first.Env, "\x00") ||
			!slices.Equal(next.Mounts, first.Mounts) {
			return SandboxMetadata{Mode: "mixed"}
		}
	}
	return first
}

func effectiveSandboxMounts(mounts []SandboxMount) []SandboxMount {
	permissions := make(map[string]bool, len(mounts))
	for _, mount := range mounts {
		path := filepath.Clean(mount.Path)
		if !filepath.IsAbs(path) {
			continue
		}
		permissions[path] = mount.Write
	}
	paths := make([]string, 0, len(permissions))
	for path := range permissions {
		paths = append(paths, path)
	}
	sort.Strings(paths)
	effective := make([]SandboxMount, 0, len(paths))
	for _, path := range paths {
		effective = append(effective, SandboxMount{Path: path, Write: permissions[path]})
	}
	return effective
}

func commandRunnerForOptions(opts Options, ctx RunContext, env map[string]string) (CommandRunner, SandboxMetadata, error) {
	metadata, err := sandboxMetadata(opts, env)
	if err != nil {
		return nil, SandboxMetadata{}, err
	}
	if ctx.CommandRunner != nil {
		return ctx.CommandRunner, metadata, nil
	}
	host := ctx.HostCommandRunner
	if host == nil {
		host = defaultCommandRunner{Env: env}
	}
	if metadata.Mode == SandboxModeOff {
		return host, metadata, nil
	}
	if requiresCommandExecution(opts) {
		availability := ctx.DockerAvailability
		if availability == nil {
			availability = dockerAvailable
		}
		if err := availability(); err != nil {
			return nil, metadata, fmt.Errorf("Docker sandbox is required for selected command-backed scanners or judge; install/start Docker or rerun with --sandbox off: %w", err)
		}
	}
	return dockerCommandRunner{
		Host:     host,
		Env:      env,
		Image:    metadata.Image,
		EnvNames: metadata.Env,
		Mounts:   metadata.Mounts,
	}, metadata, nil
}

func dockerAvailable() error {
	if _, err := exec.LookPath("docker"); err != nil {
		return err
	}
	return nil
}

func (runner dockerCommandRunner) Run(command string, args []string, cwd string, timeout time.Duration) (CommandOutput, error) {
	dockerArgs := []string{"run", "--rm", "--network", "bridge"}
	if runID := strings.TrimSpace(runner.Env[SandboxRunIDEnv]); runID != "" {
		if !sandboxRunIDPattern.MatchString(runID) {
			return CommandOutput{}, fmt.Errorf("%s must be 1-64 letters, digits, dots, underscores or hyphens, starting with a letter or digit", SandboxRunIDEnv)
		}
		dockerArgs = append(dockerArgs,
			"--label", SandboxRunIDLabel+"="+runID,
			"--label", SandboxCommandIDLabel+"="+rand.Text(),
		)
	}
	for _, name := range runner.EnvNames {
		if strings.TrimSpace(runner.Env[name]) != "" {
			dockerArgs = append(dockerArgs, "-e", name)
		}
	}
	for _, mount := range dockerMounts(cwd, args, runner.Mounts) {
		dockerArgs = append(dockerArgs, "--mount", mount)
	}
	if cwd != "" {
		dockerArgs = append(dockerArgs, "-w", cwd)
	}
	dockerArgs = append(dockerArgs, runner.Image, command)
	dockerArgs = append(dockerArgs, args...)
	return runner.Host.Run("docker", dockerArgs, "", timeout)
}

func dockerMounts(cwd string, args []string, extra []SandboxMount) []string {
	mounts := map[string]bool{}
	add := func(path string, readOnly bool) {
		if path == "" {
			return
		}
		clean := filepath.Clean(path)
		if !filepath.IsAbs(clean) {
			return
		}
		if existing, err := os.Stat(clean); err == nil {
			mounts[clean] = readOnly || !existing.IsDir()
		}
	}
	add(cwd, false)
	for _, arg := range args {
		add(arg, true)
	}
	for _, mount := range extra {
		clean := filepath.Clean(mount.Path)
		if !filepath.IsAbs(clean) {
			continue
		}
		mounts[clean] = !mount.Write
	}
	sources := make([]string, 0, len(mounts))
	for source := range mounts {
		sources = append(sources, source)
	}
	sort.Strings(sources)
	out := make([]string, 0, len(sources))
	for _, source := range sources {
		out = append(out, dockerMountSpec(source, mounts[source]))
	}
	return out
}

func dockerMountSpec(source string, readOnly bool) string {
	fields := []string{"type=bind", "source=" + source, "target=" + source}
	if readOnly {
		fields = append(fields, "readonly")
	}
	// Docker parses the entire --mount value as one CSV record. strings.Builder
	// writes cannot fail, so encoding needs no separate escaping fallback.
	var buf strings.Builder
	writer := csv.NewWriter(&buf)
	_ = writer.Write(fields)
	writer.Flush()
	return strings.TrimSuffix(buf.String(), "\n")
}

func sandboxEnvNames(opts Options, env map[string]string) []string {
	seen := map[string]bool{}
	add := func(name string) {
		name = strings.TrimSpace(name)
		if name != "" {
			seen[name] = true
		}
	}
	for _, name := range opts.Sandbox.Env {
		add(name)
	}
	for _, req := range requirements(opts, env) {
		add(req.EnvVar)
	}
	for _, scanner := range opts.Scanners {
		if opts.ScannerResultPaths[scanner] != "" {
			continue
		}
		adapter, ok := registryForOptions(opts).Adapter(scanner)
		if !ok {
			continue
		}
		info := adapter.Info()
		for _, name := range info.RequiredEnv {
			add(name)
		}
		for _, name := range info.OptionalEnv {
			if strings.TrimSpace(env[name]) != "" {
				add(name)
			}
		}
	}
	names := make([]string, 0, len(seen))
	for name := range seen {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func requiresCommandExecution(opts Options) bool {
	if opts.Judge != nil {
		return true
	}
	for _, scanner := range opts.Scanners {
		if opts.ScannerResultPaths[scanner] != "" {
			continue
		}
		adapter, ok := registryForOptions(opts).Adapter(scanner)
		if !ok {
			continue
		}
		if commandBackedScanner(adapter) {
			return true
		}
	}
	return false
}

